import{_ as a,o as t,c as s,a0 as n}from"./chunks/framework.CIbwkeYd.js";const m=JSON.parse('{"title":"Gateway Claims Ledger","description":"","frontmatter":{},"headers":[],"relativePath":"GatewayClaimsLedger.md","filePath":"GatewayClaimsLedger.md"}'),i={name:"GatewayClaimsLedger.md"};function o(l,e,d,r,c,h){return t(),s("div",null,[...e[0]||(e[0]=[n(`<h1 id="gateway-claims-ledger" tabindex="-1">Gateway Claims Ledger <a class="header-anchor" href="#gateway-claims-ledger" aria-label="Permalink to &quot;Gateway Claims Ledger&quot;">​</a></h1><p><strong>Status: Superseded entirely by the E+A signed-delegation mechanism (2026-09-13).</strong> Everything this doc describes below — the <code>netget.*</code> semantic ledger model, <code>writeToMonad()</code>-based mutation, the whole &quot;ledger is authoritative&quot; invariant — was the OLD design for <code>bootstrapOwner()</code>/<code>grantAdmin()</code>/<code>revokeAdmin()</code>/<code>transferOwner()</code>, and it is now confirmed BROKEN for a namespace-derived gateway: those methods wrote an UNSIGNED <code>writeToMonad()</code> call, which a monad holding a real <code>.me</code> claim correctly rejects (<code>NAMESPACE_WRITE_FORBIDDEN</code> — <code>commandHandler.ts</code>&#39;s <code>isNamespaceWriteAuthorized()</code> gate). Proven live in <code>modules/netget/Typescript/tests/gateway-claims-live-write-integration.test.ts</code>&#39;s own history (it originally caught this failing, before the fix below).</p><p><strong>The real model now</strong>: canonical owner/admins/grants state lives in <code>.me</code> itself, in monad.ai&#39;s new <code>claim/gatewayAuthority.ts</code> — a kernel-root, namespace-<strong>independent</strong> branch (<code>daemon.gateways.&lt;gatewayId&gt;</code>, deliberately not nested under any user&#39;s <code>users.&lt;handle&gt;</code> tree, so transferring ownership never requires moving state into a different user&#39;s personal branch), mutated only via SIGNED grant/revoke/transfer/ bootstrap calls, each independently re-verified by whichever monad holds that branch (never trusting netget&#39;s own prior check). Two checks per mutation, never conflated: &quot;vigencia&quot; (is the signing keychain key currently active — <code>getKeychainKey</code>) and &quot;autorización&quot; (does that identity currently hold gateway authority, per the branch&#39;s OWN <code>admins</code> map — never the keychain&#39;s own <code>admin</code> bit, which means something narrower: &quot;can administer THAT keychain,&quot; not &quot;can administer this gateway&quot;). <code>GatewayClaimsManager.materializeFromGatewayAuthority()</code> is netget&#39;s ONLY remaining role: a plain, unauthenticated read that refreshes the local <code>gateway-claims.json</code> cache — netget needs read access here, never write permission.</p><p><code>bootstrapOwner()</code>/<code>grantAdmin()</code>/<code>revokeAdmin()</code>/<code>transferOwner()</code> (the methods this whole doc originally described) are kept, doc-commented LEGACY in <code>GatewayClaimsManager.ts</code>, for <code>gateway-claims.test.ts</code>&#39;s own self-owned-ledger model coverage only (a real, distinct scenario: netget exclusively owning an unclaimed monad) — not the real namespace-derived flow anymore. <code>materializeFromNamespaceClaim()</code> (the base-claim-only, local-file-only method the 2026-09-12 revision of this doc described) is similarly superseded in the real flow by a real bootstrap call to <code>claim/gatewayAuthority.ts</code>&#39;s own endpoint.</p><p><strong>Behavior change worth knowing</strong>: deleting <code>gateway-claims.json</code> locally no longer means &quot;unbound&quot; (true under the OLD local-file-only base-claim model, and under this doc&#39;s OLD ledger model too) — the canonical branch on the monad is the real source of truth now, and survives a local cache wipe. See <code>gateway-setup-session.test.ts</code>&#39;s case 7h.</p><p>See session memory <code>project_mesh_announce_trust_hardening.md</code>&#39;s &quot;RESOLVED&quot; section for the full design rationale (options A-E considered, why E+A was chosen over a local-file bridge or a daemon-held delegation key), and <code>claim/gatewayAuthority.ts</code>&#39;s own header comment for the mechanism itself. Everything below this point describes the OLD, now-replaced ledger model — kept for historical context, not as current guidance.</p><hr><h2 id="the-model" tabindex="-1">The model <a class="header-anchor" href="#the-model" aria-label="Permalink to &quot;The model&quot;">​</a></h2><p>Netget runs over a designated <code>.me</code> namespace. The host is only the surface that accepted the connection; the namespace is the semantic context where durable paths live.</p><p>That means gateway authorization should be rooted in the same monad namespace that netget already uses for domain records:</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>NETGET_MONAD_NAMESPACE</span></span>
<span class="line"><span>  -&gt; xConfig.mainServerName</span></span>
<span class="line"><span>  -&gt; local.cleaker</span></span></code></pre></div><p><code>seed</code> and <code>namespace</code> stay separate:</p><ul><li><code>seed</code> is the gateway monad&#39;s cryptographic identity.</li><li><code>namespace</code> is the semantic context where writes land.</li></ul><p><code>GatewayClaimsManager</code> should not need its own namespace resolver. If it writes to netget&#39;s own monad through <code>monadHttpClient.ts</code>, the monad process already decides the namespace because it was started with <code>getGatewayRootNamespace()</code>.</p><hr><h2 id="the-gap" tabindex="-1">The gap <a class="header-anchor" href="#the-gap" aria-label="Permalink to &quot;The gap&quot;">​</a></h2><p>Historically, <code>GatewayClaimsManager.ts</code> treated the local JSON snapshot as the real source of truth:</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>~/.get/runtime/gateway-claims.json</span></span>
<span class="line"><span>~/.get/runtime/gateway-claims.version</span></span></code></pre></div><p>That JSON file is important and should stay, because nginx Lua reads it on the hot path for <code>X-Me-Proof</code> verification and scope lookup. Lua needs a local, synchronous, cheap materialized view.</p><p>The problem was that the JSON was not only a materialized view. It was the authoritative store. The mutation methods:</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>bootstrapOwner()</span></span>
<span class="line"><span>grantAdmin()</span></span>
<span class="line"><span>revokeAdmin()</span></span>
<span class="line"><span>transferOwner()</span></span></code></pre></div><p>mutated the JSON directly and never wrote to <code>.me</code> semantic memory. That made <code>gateway-claims.json</code> a second ledger parallel to the kernel.</p><p>The <code>GatewayClaimsManager</code> path is now corrected: those four methods write <code>netget.*</code> semantic paths first and then refresh the local snapshot from that ledger. The legacy browser signup path is corrected too: <code>claim_identity.lua</code> still verifies nonce/timestamp/signature at the OpenResty edge, but delegates the mutation through an internal backend route that calls <code>GatewayClaimsManager.registerIdentity()</code>.</p><p>This is the same class of failure that the domain store migration closed: a local file exists for speed, but it must not be the durable source of truth.</p><hr><h2 id="target-paths" tabindex="-1">Target paths <a class="header-anchor" href="#target-paths" aria-label="Permalink to &quot;Target paths&quot;">​</a></h2><p>Gateway authorization should live under netget&#39;s namespace as ordinary semantic paths:</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>netget.owner.identityHash       -&gt; identityHash</span></span>
<span class="line"><span>netget.owner.username           -&gt; username</span></span>
<span class="line"><span>netget.admins.&lt;identityHash&gt;    -&gt; true</span></span>
<span class="line"><span>netget.grants.&lt;identityHash&gt;    -&gt; GatewayScope[]</span></span>
<span class="line"><span>netget.pubkeys.&lt;identityHash&gt;   -&gt; Ed25519 public key</span></span>
<span class="line"><span>netget.usernames.&lt;identityHash&gt; -&gt; username</span></span></code></pre></div><p>These paths are intentionally not rooted in a physical hostname. They belong to the designated namespace, for example <code>local.cleaker</code> locally or <code>cleaker.me</code> when the operator chooses a public namespace.</p><hr><h2 id="materialized-snapshot" tabindex="-1">Materialized snapshot <a class="header-anchor" href="#materialized-snapshot" aria-label="Permalink to &quot;Materialized snapshot&quot;">​</a></h2><p><code>gateway-claims.json</code> remains the file Lua consumes:</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>.me semantic memory -&gt; GatewayClaimsManager materialization -&gt; gateway-claims.json -&gt; Lua</span></span></code></pre></div><p>The JSON shape should remain flat:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;gatewayId&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;suis-macbook-air.local&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;owner&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;...&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;admins&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {},</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;grants&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {},</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;pubkeys&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {},</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;usernames&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {},</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;version&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;...&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;updatedAt&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1780000000000</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>Lua should not call the monad per request. The monad is the source; the JSON is the cache.</p><hr><h2 id="migration-plan" tabindex="-1">Migration plan <a class="header-anchor" href="#migration-plan" aria-label="Permalink to &quot;Migration plan&quot;">​</a></h2><ol><li>✅ Add semantic write helpers to <code>GatewayClaimsManager</code> using <code>writeToMonad()</code> and <code>readFromMonad()</code> from <code>src/kernel/monadHttpClient.ts</code>.</li><li>✅ Change the four mutation methods so they first update the semantic ledger, then regenerate and flush the local JSON snapshot.</li><li>✅ Add <code>migrateGatewayClaimsToMonad.ts</code> to import an existing <code>gateway-claims.json</code> into the semantic ledger once.</li><li>✅ Keep all read-side Lua behavior pointed at the JSON snapshot.</li><li>✅ Add tests proving both layers stay aligned for <code>GatewayClaimsManager</code>.</li><li>✅ Move legacy <code>/me/claim</code> off direct JSON writes: <code>claim_identity.lua</code> verifies the proof and delegates to <code>GatewayClaimsManager.registerIdentity()</code>.</li><li>✅ Close monad <code>/api/v1/commit</code>: external semantic commits require a real claim signature and honest attribution.</li></ol><p>The synchronous read API is preserved. The mutation API is now async because monad writes are HTTP calls.</p><hr><h2 id="required-tests" tabindex="-1">Required tests <a class="header-anchor" href="#required-tests" aria-label="Permalink to &quot;Required tests&quot;">​</a></h2><p>The migration should not be considered closed until these pass:</p><ul><li>Bootstrap writes <code>netget.owner.identityHash</code>, <code>netget.admins.&lt;owner&gt;</code>, <code>netget.grants.&lt;owner&gt;</code>, and the JSON snapshot.</li><li><code>grantAdmin()</code> writes semantic memory and updates the JSON snapshot.</li><li><code>revokeAdmin()</code> tombstones the semantic admin/grant/pubkey/username paths and removes them from the JSON snapshot.</li><li>The owner cannot be revoked.</li><li><code>transferOwner()</code> changes <code>netget.owner.identityHash</code> without deleting the previous owner&#39;s admin grant.</li><li>A regenerated snapshot from semantic memory matches the current JSON shape.</li><li>Lua-visible auth still reads only <code>gateway-claims.json</code>.</li><li><code>reset()</code> tombstones owner/admin/grant/pubkey/username paths instead of only deleting the local JSON snapshot.</li></ul><p>The important invariant (as originally written — still true for <code>grantAdmin</code>/<code>revokeAdmin</code>/<code>transferOwner</code>; <strong>not</strong> how the base claim works anymore, see the status note at the top of this file):</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>semantic ledger is authoritative</span></span>
<span class="line"><span>gateway-claims.json is materialized</span></span>
<span class="line"><span>Lua consumes the materialized view</span></span></code></pre></div><p>For the base claim specifically, the invariant is now:</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>namespace&#39;s own .me claim is authoritative (verified via live keychain +</span></span>
<span class="line"><span>  Ed25519 signature at claim time, not stored again by netget)</span></span>
<span class="line"><span>gateway-claims.json is a local cache of that verification&#39;s result —</span></span>
<span class="line"><span>  losing it is a real local reset (another identity CAN then bind), not a</span></span>
<span class="line"><span>  silently-recoverable cache miss</span></span>
<span class="line"><span>Lua consumes the same materialized view, unchanged</span></span></code></pre></div><hr><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./DomainStoreSplitBrain.html">DomainStoreSplitBrain.md</a> - the already-fixed version of this same split-brain pattern for domain routing.</li><li><a href="./GatewayCapabilityModel.html">GatewayCapabilityModel.md</a> - signed capability checks that currently consume <code>gateway-claims.json</code>.</li><li><a href="./EncryptedAudienceCapabilityTests.html">EncryptedAudienceCapabilityTests.md</a> - the live proof that <code>A</code>, auth, and <code>C</code> stay separate for gateway writes.</li></ul>`,51)])])}const g=a(i,[["render",o]]);export{m as __pageData,g as default};
